'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const shape=read('docs/scifi-ui/scripts/formatx-core-shape-v14.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v15.js');
const geometry=read('docs/scifi-ui/scripts/formatx-core-geometry-v13.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v16.css');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const voice=read('docs/scifi-ui/scripts/organism-voice-stability.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');
assert.match(mapper,/fxApexSceneStability==='ready-v26'/);
assert.match(mapper,/formatx-core-cinematic-grade-v16\.css\?v=20260809-reference-calibrated-v16/);
assert.match(mapper,/fxCoreVisualCalibration='reference-luminance-saturation-v16'/);
assert.match(mapper,/cinematic-reference-calibrated-centered-glass-v26/);
assert.match(material,/vec2 cp=vec2\(vP\.x,vP\.y-\.18\)/);
assert.match(material,/fxCoreMaterialCenter='object-space-y-minus-0\.18'/);
assert.match(shape,/aPosition\.y\*\.72/);
assert.match(shape,/fxCoreShapeFracture='applied-v14'/);
assert.match(geometry,/value\*1\.15/);
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/);
assert.match(fracture,/gl\.drawElements\(gl\.LINES/);
assert.match(grade,/brightness\(1\.82\)/,'mobile reference brightness calibration missing');
assert.match(grade,/saturate\(1\.06\)/,'mobile reference saturation calibration missing');
assert.match(grade,/opacity: 0\.50/,'mobile fracture detail calibration missing');
assert.match(grade,/brightness\(1\.75\)/,'desktop reference brightness calibration missing');
assert.match(grade,/opacity: 0\.54/,'desktop fracture detail calibration missing');
assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s);
assert.match(voice,/window\.visualViewport/);
assert.match(infinite,/const VERSION = 'seamless-v7'/);
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/);
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/);
console.log('PASS: v16 keeps centered real 3D MAG geometry/material and applies measured reference luminance, saturation and fracture-detail calibration without scroll regressions.');
